import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state holder.
///
/// Text changes are stored immediately, but a fetch only starts once the
/// debounce duration has elapsed without another change. Responses that no
/// longer match the current query are dropped, so stale results can never
/// overwrite newer ones.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Incremented whenever the query changes or the model is disposed, so that
  /// in-flight fetches started for an older value can be identified and
  /// discarded.
  int _generation = 0;
  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch. Unmodifiable.
  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    final generation = _generation;
    _timer = Timer(_debounce, () => _fetch(text, generation));
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final values = await _fetcher(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _status = SearchStatus.success;
      _error = null;
    } catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _generation++;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the most recent search.
enum SearchStatus { idle, loading, success, error }

/// Runs a [SearchFetcher] over the typed query, debounced, and exposes the
/// state of the search to listeners.
///
/// Only the fetch for the query that is still current can change the state:
/// responses that arrive for an outdated query are dropped, whatever the
/// order in which the fetches complete.
class SearchModel extends ChangeNotifier {
  /// Creates a model that searches with [fetcher] once [debounce] has passed
  /// without a further change.
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : this._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the fetch whose result is still wanted. Bumping it drops
  /// whatever is in flight.
  int _requestId = 0;

  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  /// The state of the latest search.
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch, unmodifiable.
  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  /// Records [text] as the current query and schedules a fetch for it.
  ///
  /// Text equal to the current query changes nothing; an empty query resets
  /// the model to [SearchStatus.idle] without fetching.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      _requestId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounce, () {
      _timer = null;
      unawaited(_fetch(text));
    });
  }

  Future<void> _fetch(String text) async {
    if (_disposed) {
      return;
    }
    final int id = ++_requestId;
    _status = SearchStatus.loading;
    notifyListeners();

    try {
      final List<String> fetched = await _fetcher(text);
      if (_disposed || id != _requestId) {
        return;
      }
      _results = List<String>.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_disposed || id != _requestId) {
        return;
      }
      _error = error;
      _results = const <String>[];
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// User-facing configuration that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// The account name. Never empty.
  final String username;

  /// The editor font size, always within [minFontSize] .. [maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is selected.
  final bool darkMode;

  /// Free-form labels. Never contains an empty entry.
  final List<String> tags;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be turned into a [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable description of the problem.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value is not a JSON object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('key "$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('key "$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double) {
    if (!value.isFinite || value != value.roundToDouble()) {
      throw const SettingsFormatException('key "$key" must be an integer');
    }
    size = value.toInt();
  } else {
    throw const SettingsFormatException('key "$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'key "$key" must be between ${Settings.minFontSize} '
      'and ${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('key "$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('key "$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException(
        'key "$key" must contain only strings',
      );
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        'key "$key" must not contain empty strings',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

import 'dart:convert';

/// User preferences for the app.
///
/// The invariants documented on each field are enforced by [parseSettings];
/// values built in code are trusted.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// The account name. Never empty.
  final String username;

  /// The editor font size, between [minFontSize] and [maxFontSize] inclusive.
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// Free-form labels. Never contains an empty tag.
  final List<String> tags;

  /// The smallest accepted [fontSize].
  static const int minFontSize = 8;

  /// The largest accepted [fontSize].
  static const int maxFontSize = 72;

  /// A JSON representation that [parseSettings] reads back into an equal value.
  Map<String, Object?> toJson() {
    return <String, Object?>{
      _usernameKey: username,
      _fontSizeKey: fontSize,
      _darkModeKey: darkMode,
      _tagsKey: List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] when a document cannot be read as [Settings].
///
/// The [message] names the offending key whenever one can be identified.
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

const String _usernameKey = 'username';
const String _fontSizeKey = 'fontSize';
const String _darkModeKey = 'darkMode';
const String _tagsKey = 'tags';

/// Reads a [Settings] value from a JSON document.
///
/// Throws a [SettingsFormatException] — and nothing else — when [json] is not
/// valid JSON, when its top level is not an object, or when a key is missing,
/// has the wrong type, or falls outside its accepted range. Keys other than
/// `username`, `fontSize`, `darkMode` and `tags` are ignored.
Settings parseSettings(String json) {
  final Object? decoded = _decode(json);
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

Object? _decode(String json) {
  try {
    return jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'The document is not valid JSON: '
      '${error.message}',
    );
  }
}

String _readUsername(Map<String, Object?> json) {
  final Object? value = json[_usernameKey];
  if (value == null) {
    throw const SettingsFormatException(
      'The required key "$_usernameKey" is missing.',
    );
  }
  if (value is! String) {
    throw const SettingsFormatException(
      'The key "$_usernameKey" must hold a string.',
    );
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      'The key "$_usernameKey" must not be empty.',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey(_fontSizeKey)) {
    return 14;
  }
  final Object? value = json[_fontSizeKey];
  final int fontSize;
  if (value is int) {
    fontSize = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    fontSize = value.toInt();
  } else {
    throw const SettingsFormatException(
      'The key "$_fontSizeKey" must hold a whole number.',
    );
  }
  if (fontSize < Settings.minFontSize || fontSize > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'The key "$_fontSizeKey" must be between ${Settings.minFontSize} and '
      '${Settings.maxFontSize}.',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey(_darkModeKey)) {
    return false;
  }
  final Object? value = json[_darkModeKey];
  if (value is! bool) {
    throw const SettingsFormatException(
      'The key "$_darkModeKey" must hold a boolean.',
    );
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey(_tagsKey)) {
    return const <String>[];
  }
  final Object? value = json[_tagsKey];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'The key "$_tagsKey" must hold a list of strings.',
    );
  }
  final List<String> tags = <String>[];
  for (final Object? element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        'The key "$_tagsKey" must hold a list of strings.',
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        'The key "$_tagsKey" must not contain an empty tag.',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

bool _tagsEqual(List<String> a, List<String> b) {
  if (identical(a, b)) {
    return true;
  }
  if (a.length != b.length) {
    return false;
  }
  for (int i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Runs the search for [query] and completes with the matching entries.
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the most recent search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and exposes the result of the latest search.
class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  /// Incremented on every accepted query change, so a response can tell
  /// whether the query it was started for is still the current one.
  var _generation = 0;
  Timer? _timer;
  var _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  var _query = '';
  List<String> _results = const [];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] as the current query and schedules a fetch for it once
  /// [_debounce] has passed without a further change.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _generation++;
    _timer?.cancel();
    _timer = null;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
    } else {
      final generation = _generation;
      _timer = Timer(_debounce, () {
        unawaited(_fetch(text, generation));
      });
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    try {
      final values = await _fetcher(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(values);
      _error = null;
    } on Object catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = const [];
      _error = error;
    }
    notifyListeners();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const _tickInterval = Duration(seconds: 1);

String _formatDuration(Duration value) {
  final minutes = value.inMinutes.toString().padLeft(2, '0');
  final seconds = (value.inSeconds % Duration.secondsPerMinute)
      .toString()
      .padLeft(2, '0');
  return '$minutes:$seconds';
}

class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : assert(!duration.isNegative, 'duration must not be negative'),
      _duration = duration,
      _remaining = duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tickInterval, _onTick);
    notifyListeners();
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }

  void _onTick(Timer timer) {
    final next = _remaining - _tickInterval;
    if (next > Duration.zero) {
      _remaining = next;
    } else {
      _remaining = Duration.zero;
      _cancelTimer();
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }
}

class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late Duration _remaining = widget.controller.remaining;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onControllerChanged);
      widget.controller.addListener(_onControllerChanged);
      _remaining = widget.controller.remaining;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text(_formatDuration(_remaining)),
      Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          TextButton(
            onPressed: widget.controller.start,
            child: const Text('Start'),
          ),
          TextButton(
            onPressed: widget.controller.pause,
            child: const Text('Pause'),
          ),
          TextButton(
            onPressed: widget.controller.reset,
            child: const Text('Reset'),
          ),
        ],
      ),
    ],
  );

  void _onControllerChanged() {
    if (!mounted) {
      return;
    }
    final remaining = widget.controller.remaining;
    final finished = remaining == Duration.zero && _remaining > Duration.zero;
    setState(() {
      _remaining = remaining;
    });
    if (finished) {
      widget.onFinished?.call();
    }
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

const _minFontSize = 8;
const _maxFontSize = 72;
const _defaultFontSize = 14;

/// User preferences that survive a round trip through JSON.
@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;

  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] for every input it refuses.
class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Reads a [Settings] from a JSON object, throwing
/// [SettingsFormatException] for anything else.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('Not valid JSON: ${error.message}');
  }
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level value must be a JSON object.',
    );
  }
  return Settings(
    username: _parseUsername(decoded),
    fontSize: _parseFontSize(decoded),
    darkMode: _parseDarkMode(decoded),
    tags: _parseTags(decoded),
  );
}

String _parseUsername(Map<String, Object?> json) {
  final value = json['username'];
  if (value is! String) {
    throw const SettingsFormatException("Key 'username' must be a string.");
  }
  if (value.isEmpty) {
    throw const SettingsFormatException("Key 'username' must not be empty.");
  }
  return value;
}

int _parseFontSize(Map<String, Object?> json) {
  final value = json['fontSize'];
  if (value == null) {
    return _defaultFontSize;
  }
  if (value is! num) {
    throw const SettingsFormatException("Key 'fontSize' must be an integer.");
  }
  final fontSize = value.toInt();
  if (fontSize != value) {
    throw const SettingsFormatException(
      "Key 'fontSize' must not have a fractional part.",
    );
  }
  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    throw const SettingsFormatException(
      "Key 'fontSize' must be between $_minFontSize and $_maxFontSize.",
    );
  }
  return fontSize;
}

bool _parseDarkMode(Map<String, Object?> json) {
  final value = json['darkMode'];
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException("Key 'darkMode' must be a boolean.");
  }
  return value;
}

List<String> _parseTags(Map<String, Object?> json) {
  final value = json['tags'];
  if (value == null) {
    return const [];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      "Key 'tags' must be a list of strings.",
    );
  }
  final tags = <String>[];
  for (final element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        "Key 'tags' must contain strings only.",
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        "Key 'tags' must not contain an empty string.",
      );
    }
    tags.add(element);
  }
  return tags;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// The interval between two ticks of a running countdown.
const _tick = Duration(seconds: 1);

/// Counts down from a fixed duration to zero, one second at a time.
///
/// The object that creates the controller also owns it and is responsible
/// for calling [dispose], which cancels a running countdown.
class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  final Duration _duration;
  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while running or once [remaining] is zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
  }

  /// Stops ticking and keeps [remaining]. Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to the initial duration.
  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }

  void _onTick() {
    final next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the remaining time of [controller] as `mm:ss` with controls for it.
///
/// The controller is owned by the caller: this widget only listens to it and
/// never disposes it, so the same controller can be handed to another
/// [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleTick);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller == widget.controller) {
      return;
    }
    oldWidget.controller.removeListener(_handleTick);
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleTick);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleTick);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text(_format(widget.controller.remaining)),
      Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          TextButton(
            onPressed: widget.controller.start,
            child: const Text('Start'),
          ),
          TextButton(
            onPressed: widget.controller.pause,
            child: const Text('Pause'),
          ),
          TextButton(
            onPressed: widget.controller.reset,
            child: const Text('Reset'),
          ),
        ],
      ),
    ],
  );

  void _handleTick() {
    setState(() {});
    if (widget.controller.remaining > Duration.zero) {
      _finished = false;
      return;
    }
    if (_finished) {
      return;
    }
    _finished = true;
    widget.onFinished?.call();
  }

  String _format(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute).toString();
    return '$minutes:${seconds.padLeft(2, '0')}';
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

const _minFontSize = 8;
const _maxFontSize = 72;

/// User preferences that survive a round trip through JSON.
@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;

  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] for any input it cannot turn into [Settings].
class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses a JSON object into [Settings].
///
/// Throws a [SettingsFormatException] when [json] is not a JSON object, when a
/// required key is missing, or when a value has the wrong type or lies outside
/// its range. Unknown keys are ignored.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json) as Object?;
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('the top level is not a JSON object');
  }
  return Settings(
    username: _username(decoded),
    fontSize: _fontSize(decoded),
    darkMode: _darkMode(decoded),
    tags: _tags(decoded),
  );
}

String _username(Map<String, Object?> map) {
  final value = map['username'];
  if (value is! String) {
    throw const SettingsFormatException('username must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('username must not be empty');
  }
  return value;
}

int _fontSize(Map<String, Object?> map) {
  if (!map.containsKey('fontSize')) {
    return 14;
  }
  final value = map['fontSize'];
  if (value is! int) {
    throw const SettingsFormatException('fontSize must be a whole number');
  }
  if (value < _minFontSize || value > _maxFontSize) {
    throw const SettingsFormatException(
      'fontSize must be between $_minFontSize and $_maxFontSize',
    );
  }
  return value;
}

bool _darkMode(Map<String, Object?> map) {
  if (!map.containsKey('darkMode')) {
    return false;
  }
  final value = map['darkMode'];
  if (value is! bool) {
    throw const SettingsFormatException('darkMode must be a boolean');
  }
  return value;
}

List<String> _tags(Map<String, Object?> map) {
  if (!map.containsKey('tags')) {
    return const [];
  }
  final value = map['tags'];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('tags must be a list of strings');
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String) {
      throw const SettingsFormatException('tags must contain only strings');
    }
    if (tag.isEmpty) {
      throw const SettingsFormatException('tags must not contain empty tags');
    }
    tags.add(tag);
  }
  return List.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search a [SearchModel] knows about.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state: the newest query wins, stale answers are dropped.
class SearchModel extends ChangeNotifier {
  /// Searches with [fetcher] once [debounce] passed without a new query.
  new({required SearchFetcher fetcher, Duration debounce = _defaultDebounce})
    : _search = fetcher,
      _debounceDelay = debounce;

  static const _defaultDebounce = Duration(milliseconds: 300);

  final SearchFetcher _search;
  final Duration _debounceDelay;

  Timer? _timer;
  var _query = '';
  var _status = SearchStatus.idle;
  var _results = const <String>[];
  Object? _error;

  /// Identifies the current query; an answer to an older one is stale.
  var _generation = 0;
  var _disposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] and schedules a fetch for it once the debounce elapses.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _error = null;
    _timer?.cancel();
    _generation++;
    if (text.isEmpty) {
      _timer = null;
      _status = SearchStatus.idle;
      _results = const [];
    } else {
      _status = SearchStatus.loading;
      final generation = _generation;
      _timer = Timer(_debounceDelay, () => unawaited(_fetch(text, generation)));
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed) {
      return;
    }
    try {
      final items = await _search(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(items);
      _error = null;
    } on Object catch (e) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = const [];
      _error = e;
    }
    notifyListeners();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const _oneSecond = Duration(seconds: 1);

/// Counts down from the given duration to zero, one second at a time.
class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_oneSecond, _tick);
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
  }

  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _tick(Timer timer) {
    _remaining -= _oneSecond;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time and drives it from three buttons.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChange);
      widget.controller.addListener(_handleControllerChange);
      _finished = widget.controller.remaining == Duration.zero;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChange);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_format(controller.remaining)),
        TextButton(onPressed: controller.start, child: const Text('Start')),
        TextButton(onPressed: controller.pause, child: const Text('Pause')),
        TextButton(onPressed: controller.reset, child: const Text('Reset')),
      ],
    );
  }

  void _handleControllerChange() {
    final finished = widget.controller.remaining == Duration.zero;
    setState(() {});
    if (finished && !_finished) {
      widget.onFinished?.call();
    }
    _finished = finished;
  }

  String _format(Duration remaining) {
    final minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final seconds = (remaining.inSeconds % 60).toString().padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results matching [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the search for the current query.
enum SearchStatus {
  /// No query is being searched for.
  idle,

  /// A fetch for the current query is in flight.
  loading,

  /// The fetch for the current query completed.
  success,

  /// The fetch for the current query threw.
  error,
}

/// Searches with [SearchFetcher] for the text passed to [onQueryChanged],
/// debouncing the calls and discarding results that arrive for a query that
/// is no longer current.
class SearchModel extends ChangeNotifier {
  /// Creates a model that searches with `fetcher` once `debounce` has passed
  /// without a further change of the query.
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the latest query, so that a response of an earlier one can be
  /// recognised and dropped.
  var _requestId = 0;

  var _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;

  /// The state of the search for [query].
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch, empty otherwise.
  ///
  /// The list is unmodifiable.
  List<String> get results => _results;

  /// The object thrown by the latest failed fetch, `null` otherwise.
  Object? get error => _error;

  /// Stores [text] as the current [query] and schedules a fetch for it.
  ///
  /// Text equal to the current [query] does nothing. An empty text clears the
  /// results and the error and leaves the status [SearchStatus.idle].
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight is now for an earlier query.
    _requestId++;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
    } else {
      final requestId = _requestId;
      _timer = Timer(_debounce, () => unawaited(_fetch(text, requestId)));
    }
    notifyListeners();
  }

  Future<void> _fetch(String text, int requestId) async {
    if (_isStale(requestId)) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    try {
      final values = await _fetcher(text);
      if (_isStale(requestId)) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_isStale(requestId)) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  bool _isStale(int requestId) => _disposed || requestId != _requestId;

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

/// Thrown by [parseSettings] when a document cannot be read as [Settings].
///
/// The [message] always names the offending key when one key is at fault.
class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences, as stored in a JSON document.
///
/// The constructor does not validate; [parseSettings] is the checked entry
/// point and rejects an empty [username], a [fontSize] outside
/// [minFontSize]..[maxFontSize], and an empty tag.
@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = defaultFontSize,
    this.darkMode = false,
    this.tags = const [],
  });

  /// Smallest accepted [fontSize].
  static const minFontSize = 8;

  /// Largest accepted [fontSize].
  static const maxFontSize = 72;

  /// Value used when the `fontSize` key is absent.
  static const defaultFontSize = 14;

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;

  /// The JSON representation read back by [parseSettings].
  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Reads [json] as a settings document.
///
/// Throws [SettingsFormatException], and nothing else, for any input that is
/// not a settings document. Unknown keys are ignored.
Settings parseSettings(String json) {
  final Object? document;
  try {
    document = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException('top level must be a JSON object');
  }
  return Settings(
    username: _readUsername(document),
    fontSize: _readFontSize(document),
    darkMode: _readDarkMode(document),
    tags: _readTags(document),
  );
}

String _readUsername(Map<String, Object?> document) {
  final value = document['username'];
  if (value is! String) {
    throw const SettingsFormatException('username: expected a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('username: must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> document) {
  final value = document['fontSize'];
  if (value == null) {
    return Settings.defaultFontSize;
  }
  if (value is! num || !value.isFinite) {
    throw const SettingsFormatException('fontSize: expected an integer');
  }
  final fontSize = value.toInt();
  if (fontSize != value) {
    throw const SettingsFormatException(
      'fontSize: expected an integer without a fractional part',
    );
  }
  if (fontSize < Settings.minFontSize || fontSize > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'fontSize: must be between '
      '${Settings.minFontSize} and ${Settings.maxFontSize}',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> document) {
  final value = document['darkMode'];
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException('darkMode: expected a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> document) {
  final value = document['tags'];
  if (value == null) {
    return const [];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException('tags: expected a list of strings');
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String) {
      throw const SettingsFormatException('tags: every entry must be a string');
    }
    if (tag.isEmpty) {
      throw const SettingsFormatException('tags: no entry may be empty');
    }
    tags.add(tag);
  }
  return List.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from a fixed duration to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose], which also cancels a running countdown.
class CountdownController extends ChangeNotifier {
  new({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown reaches zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking; does nothing while running or once [remaining] is zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking and keeps [remaining]; does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to the configured duration.
  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }

  void _onTick() {
    final next = _remaining - _tick;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _cancelTimer();
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` with start, pause and
/// reset buttons.
///
/// The controller is owned by the caller: this widget never disposes it, so the
/// same controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = _isFinished(widget.controller);
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = _isFinished(widget.controller);
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_format(controller.remaining)),
        TextButton(onPressed: controller.start, child: const Text('Start')),
        TextButton(onPressed: controller.pause, child: const Text('Pause')),
        TextButton(onPressed: controller.reset, child: const Text('Reset')),
      ],
    );
  }

  bool _isFinished(CountdownController controller) =>
      !controller.isRunning && controller.remaining == Duration.zero;

  void _handleControllerChanged() {
    if (!mounted) {
      return;
    }
    final finished = _isFinished(widget.controller);
    final justFinished = finished && !_finished;
    setState(() {
      _finished = finished;
    });
    if (justFinished) {
      widget.onFinished?.call();
    }
  }

  String _format(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

/// Debounced search state: the latest query wins, stale responses are dropped.
class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the newest request; a response with a stale id is discarded.
  var _requestId = 0;
  var _disposed = false;

  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight belongs to an earlier query now.
    final id = ++_requestId;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
    } else {
      _timer = Timer(_debounce, () {
        unawaited(_fetch(text, id));
      });
    }
    notifyListeners();
  }

  Future<void> _fetch(String text, int id) async {
    _timer = null;
    if (_disposed || id != _requestId) {
      return;
    }
    _status = SearchStatus.loading;
    notifyListeners();
    try {
      final values = await _fetcher(text);
      if (_disposed || id != _requestId) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_disposed || id != _requestId) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

