            child: const Text('Reset'),
          ),
        ],
      ),
    ],
  );

  void _handleChange() {
    final remaining = widget.controller.remaining;
    final finished = remaining == Duration.zero && _previous > Duration.zero;
    _previous = remaining;
    if (mounted) {
